Graph.CDATA:
using PX.Data;
using PX.Objects.FA;

namespace PX.Objects.FA
{
    public class AssetMaint_CompanyCounterExt : PXGraphExtension<AssetMaint>
    {
        public static bool IsActive() => true;

        [PXMergeAttributes(Method = MergeMethod.Replace)]
        [FACompanyPrefixAutoNumber(typeof(FASetup.assetNumberingID), typeof(AccessInfo.businessDate))]
        protected virtual void FixedAsset_AssetCD_CacheAttached(PXCache sender) { }

        protected virtual void _(Events.RowSelected<FixedAsset> e)
        {
            var row = e.Row;
            if (row?.BranchID == null) return;
            if (!string.IsNullOrEmpty(row.AssetCD) && row.AssetCD.Trim() != "<NEW>") return; // already numbered

            if (!FACompanyPrefixAutoNumberAttribute.TryResolveCompanyCode(Base, row.BranchID, out var unusedCache, out string errorMessage))
            {
                e.Cache.RaiseExceptionHandling<FixedAsset.branchID>(row, row.BranchID,
                    new PXSetPropertyException(errorMessage, PXErrorLevel.Warning));
            }
        }
   }
}
